#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
} Deque;

Deque arr[200005];
int N, M, Q;
int ops[200005];

void init() {
    for (int i = 0; i < N; i++) {
        arr[i].head = arr[i].tail = NULL;
        for (int j = 1; j <= M; j++) {
            Node *node = (Node*)malloc(sizeof(Node));
            node->val = j;
            node->prev = arr[i].tail;
            node->next = NULL;
            if (arr[i].tail) arr[i].tail->next = node;
            else arr[i].head = node;
            arr[i].tail = node;
        }
    }
}

void moveToFront(int idx, int val) {
    // find node with val in array idx
    Node *cur = arr[idx].head;
    while (cur && cur->val != val) cur = cur->next;
    if (!cur || cur == arr[idx].head) return;

    // remove cur from its position
    if (cur->prev) cur->prev->next = cur->next;
    if (cur->next) cur->next->prev = cur->prev;
    if (cur == arr[idx].tail) arr[idx].tail = cur->prev;

    // insert at front
    cur->next = arr[idx].head;
    cur->prev = NULL;
    if (arr[idx].head) arr[idx].head->prev = cur;
    arr[idx].head = cur;
    if (!arr[idx].tail) arr[idx].tail = cur;
}

int main() {
    scanf("%d %d %d", &N, &M, &Q);
    for (int i = 0; i < Q; i++) scanf("%d", &ops[i]);
    init();

    // Process in reverse
    for (int i = Q - 1; i >= 0; i--) {
        int val = ops[i];
        // Check all arrays start with same value
        int firstVal = arr[0].head->val;
        for (int j = 1; j < N; j++) {
            if (arr[j].head->val != firstVal) {
                printf("No\n");
                return 0;
            }
        }
        // They all start with val
        if (firstVal != val) {
            printf("No\n");
            return 0;
        }
        // Reverse operation: we need to remove the first element of each array
        for (int j = 0; j < N; j++) {
            Node *tmp = arr[j].head;
            arr[j].head = tmp->next;
            if (arr[j].head) arr[j].head->prev = NULL;
            else arr[j].tail = NULL;
            free(tmp);
        }
    }
    // After all reverse ops, check final state: all arrays must be identical (same order)
    Node *cur = arr[0].head;
    for (int i = 0; i < N; i++) {
        Node *cmp = arr[i].head;
        while (cur && cmp) {
            if (cur->val != cmp->val) {
                printf("No\n");
                return 0;
            }
            cur = cur->next;
            cmp = cmp->next;
        }
        if (cur || cmp) {
            printf("No\n");
            return 0;
        }
        cur = arr[0].head;
    }
    printf("Yes\n");
    return 0;
}

