#include <stdio.h>
#include <stdlib.h>

int main(void) {
    long long N;
    int M, Q;
    if (scanf("%lld %d %d", &N, &M, &Q) != 3) return 0;

    int *seen = (int *)calloc((size_t)M + 1, sizeof(int));
    int distinct = 0;

    for (int i = 0; i < Q; i++) {
        int a;
        scanf("%d", &a);
        if (!seen[a]) {
            seen[a] = 1;
            distinct++;
        }
    }

    free(seen);

    /*
      After all operations, any array is determined only by the subsequence
      of values moved to that array, considering only each value's last move.
      The front part becomes values ordered by their last move time descending,
      and the remaining values stay in increasing order.

      To make all arrays identical:
      - Every value that appears in any operation must be moved at least once
        in every array; otherwise some arrays place it in the front part and
        others in the suffix, causing mismatch.
      - Thus each array needs at least D moves, where D = number of distinct
        values among all operations.

      Since there are Q total moves over N arrays, this is possible iff
          Q >= N * D.
    */

    if ((long long)distinct * N <= (long long)Q) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }

    return 0;
}

