    vector<vector<int>> pos(N, vector<int>(M));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            pos[i][j] = j; // initially value j+1 is at position j
        }
    }

    vector<int> frontCount(N, 0); // how many numbers have been moved to front
    vector<int> lastMove(M, -1);  // last array that moved this value

    for (int i = 0; i < Q; i++) {
        int a;
        cin >> a;
        a--; // zero-based
        // We can move to front of any array. Choose the one that helps uniformity.
        // Strategy: pick the array where this number currently has the largest position
        // (i.e., furthest from front), or any if equal.
        int bestArr = 0;
        int bestPos = pos[0][a];
        for (int j = 1; j < N; j++) {
            if (pos[j][a] > bestPos) {
                bestPos = pos[j][a];
                bestArr = j;
            }
        }
        // Move a to front in bestArr
        // Shift positions of all values that were before it
        for (int v = 0; v < M; v++) {
            if (pos[bestArr][v] < pos[bestArr][a]) {
                pos[bestArr][v]++;
            }
        }
        pos[bestArr][a] = 0;
        lastMove[a] = bestArr;
    }

    // Check if all arrays same
    bool ok = true;
    for (int v = 0; v < M && ok; v++) {
        int refPos = pos[0][v];
        for (int i = 1; i < N; i++) {
            if (pos[i][v] != refPos) {
                ok = false;
                break;
            }
        }
    }

    cout << (ok ? "Yes" : "No") << "\n";

