    long long N, M, Q;
    cin >> N >> M >> Q;

    vector<long long> a(Q);
    for (int i = 0; i < Q; i++) cin >> a[i];

    // Remove consecutive duplicates, since moving the same value to front
    // repeatedly has the same effect as doing it once.
    vector<long long> b;
    for (long long x : a) {
        if (b.empty() || b.back() != x) b.push_back(x);
    }

    // Let K be the number of distinct values that appear in b.
    // To make all arrays identical, each distinct value must be moved to front
    // at least once in every array where it needs to be placed.
    // Since one operation affects only one array, we need at least N moves
    // for each distinct value except possibly those already in correct place.
    //
    // The known necessary and sufficient condition is:
    // number of distinct values in b <= (M - 1) / (N - 1) + 1
    // which is equivalent to:
    // (distinct_count - 1) * (N - 1) <= M - 1
    //
    // For N = 1, it's always possible.
    if (N == 1) {
        cout << "Yes\n";
        return 0;
    }

    set<long long> st(b.begin(), b.end());
    long long K = (long long)st.size();

    if ((K - 1) * (N - 1) <= M - 1) cout << "Yes\n";
    else cout << "No\n";

    return 0;
}

