import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int Q = fs.nextInt();

        int[] a = new int[Q];
        for (int i = 0; i < Q; i++) a[i] = fs.nextInt();

        // Remove consecutive duplicates from the operation sequence.
        ArrayList<Integer> b = new ArrayList<>();
        for (int x : a) {
            if (b.isEmpty() || b.get(b.size() - 1) != x) b.add(x);
        }

        // If the number of distinct "front blocks" exceeds N, impossible.
        if (b.size() > N) {
            System.out.println("No");
            return;
        }

        // Each array starts as [1,2,...,M].
        // After operations, an array is determined by the subsequence of values
        // moved to its front, in reverse chronological order, followed by the
        // remaining untouched values in increasing order.
        //
        // To make all arrays identical, the final common array must begin with
        // the deduplicated operation sequence in reverse: last new value first.
        // Therefore, among the remaining suffix values, their original order must
        // be compatible. This is possible iff the values never appearing in b
        // can fill the rest, and the reversed b itself is consistent with the
        // base order after removing duplicates. That happens exactly when, scanning
        // b from the end, the values are strictly increasing whenever they are
        // first encountered from the end.
        //
        // Equivalently, reversed(b) must be increasing after removing duplicates,
        // but b already has no consecutive duplicates, and every occurrence matters.
        // The known criterion simplifies to:
        // the sequence of first appearances from the end must be increasing.
        boolean[] seen = new boolean[M + 1];
        int last = 0;
        for (int i = b.size() - 1; i >= 0; i--) {
            int x = b.get(i);
            if (!seen[x]) {
                if (x < last) {
                    System.out.println("No");
                    return;
                }
                last = x;
                seen[x] = true;
            }
        }

        System.out.println("Yes");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
